/* The 68000 interpreter: exceptions, interrupts and the step loop. The
 * instruction handlers are generated by m68k_gen from the templates
 * (m68k.c); an address error leaves a handler by longjmp. */
#include "m68k_ops.h"

#include "m68k_handlers.inc"

void m68k_set_sr(M68k *c, uint16_t sr) {
    sr &= 0xA71F;
    if ((sr ^ c->sr) & M68K_S) {  /* swap the stack pointers */
        if (sr & M68K_S) c->usp = c->a[7], c->a[7] = c->ssp;
        else c->ssp = c->a[7], c->a[7] = c->usp;
    }
    c->sr = sr;
}

/* Supervisor mode, trace off; the old SR. */
static uint16_t enter(M68k *c) {
    uint16_t old = c->sr;
    m68k_set_sr(c, (uint16_t)((c->sr | M68K_S) & ~M68K_T));
    return old;
}
/* The vector's new PC, read, and the queue filled from it. */
static uint32_t vector_jump(M68k *c, int vector) {
    uint32_t hi = bus_r(c, (uint32_t)vector * 4, 5, 3);
    uint32_t pc = hi << 16 | bus_r(c, (uint32_t)vector * 4 + 2, 5, 3);
    if (pc & 1) m68k_address_error(c, pc, 0, 1, 3);
    c->ir = bus_r(c, pc, 6, 3);
    idle(c, 2);
    c->irc = bus_r(c, pc + 2, 6, 3);
    return c->pc = pc + 4;
}
/* Group 1 and 2: PC and SR pushed (the low PC word first). */
uint32_t m68k_exception(M68k *c, int vector, uint32_t pc, unsigned pre_idle) {
    uint16_t sr = enter(c);
    if (pre_idle) idle(c, pre_idle);
    c->a[7] -= 6;
    bus_w(c, c->a[7] + 4, (uint16_t)pc, 5, 3);
    bus_w(c, c->a[7], sr, 5, 3);
    bus_w(c, c->a[7] + 2, (uint16_t)(pc >> 16), 5, 3);
    return vector_jump(c, vector);
}
uint32_t m68k_privilege(M68k *c) { return m68k_exception(c, 8, c->pc - 4, 4); }

/* Group 0: the access is dropped, a 7-word frame (status: the opcode's
 * upper bits, read/write, function code; the address; IR; SR; PC). */
void m68k_address_error(M68k *c, uint32_t a, int write, int prog, unsigned strobe) {
    unsigned fc = prog ? fcp(c) : fcd(c);
    c->cycles += 4;
    m68k_aborted(c, a & 0xFFFFFF, fc, strobe, write);
    idle(c, 8);
    uint32_t pc = c->pc + (uint32_t)(int32_t)c->ae_adj;
    uint16_t sr = enter(c);
    /* IR is the queue's: after the instruction's last refill, the next opcode */
    uint16_t status = (uint16_t)((c->ir & ~0x1F) | (write ? 0 : 0x10) | fc);
    c->a[7] -= 14;
    uint32_t sp = c->a[7];
    bus_w(c, sp + 12, (uint16_t)pc, 5, 3);
    bus_w(c, sp + 8, sr, 5, 3);
    bus_w(c, sp + 10, (uint16_t)(pc >> 16), 5, 3);
    bus_w(c, sp + 6, c->ir, 5, 3);
    bus_w(c, sp + 4, (uint16_t)a, 5, 3);
    bus_w(c, sp, status, 5, 3);
    bus_w(c, sp + 2, (uint16_t)(a >> 16), 5, 3);
    c->ae_adj = -2;
    (void)vector_jump(c, 3);
    longjmp(c->abort, 1);
}

void m68k_reset(M68k *c) {
    c->sr = 0x2700;
    c->stopped = c->halted = 0;
    uint32_t hi = bus_r(c, 0, 6, 3);
    c->a[7] = c->ssp = hi << 16 | bus_r(c, 2, 6, 3);
    hi = bus_r(c, 4, 6, 3);
    uint32_t pc = hi << 16 | bus_r(c, 6, 6, 3);
    c->ir = bus_r(c, pc, 6, 3);
    c->irc = bus_r(c, pc + 2, 6, 3);
    c->pc = pc + 4;
}

/* An interrupt above the mask (level 7 always, on its edge). */
static int interrupt(M68k *c) {
    int level = c->ipl, mask = c->sr >> 8 & 7;
    int nmi = level == 7 && !c->ipl_seen;
    c->ipl_seen = level == 7;
    if (level <= mask && !nmi) return 0;
    c->stopped = 0;
    uint16_t sr = enter(c);
    c->sr = (uint16_t)((c->sr & ~0x700) | level << 8);
    idle(c, 6);
    c->a[7] -= 6;
    bus_w(c, c->a[7] + 4, (uint16_t)(c->pc - 4), 5, 3);
    int vector = m68k_iack(c, level);
    c->cycles += 4;
    if (vector < 0) vector = 24 + level;
    idle(c, 4);
    bus_w(c, c->a[7], sr, 5, 3);
    bus_w(c, c->a[7] + 2, (uint16_t)((c->pc - 4) >> 16), 5, 3);
    (void)vector_jump(c, vector);
    return 1;
}

void m68k_step(M68k *c) {
    if (c->halted) { idle(c, 4); return; }
    c->ae_adj = -2;
    if (setjmp(c->abort)) return;
    if (c->trace) {  /* T was set at the last instruction */
        c->trace = 0;
        c->op = c->ir;
        (void)m68k_exception(c, 9, c->pc - 4, 4);
        return;
    }
    if ((c->ipl || c->ipl_seen) && interrupt(c)) return;
    if (c->stopped) { idle(c, 4); return; }
    c->trace = (c->sr & M68K_T) != 0;
    c->op = c->ir;
    m68k_handlers[m68k_index[c->op]](c, c->op);
}
